package com.tankecho.zensudoku.tests;
import android.app.*;import android.content.*;import android.os.*;import java.nio.file.*;import java.io.*;import org.json.*;import java.util.*;
public class LegacyV17 extends V17DeviceTests{
 @Override public void onStart(){Bundle out=new Bundle();try{JSONObject old=new JSONObject(new String(Files.readAllBytes(new File(getTargetContext().getFilesDir(),"v17-legacy.json").toPath()),"UTF-8"));String name="legacy-v17-"+System.nanoTime();Context sandbox=new ContextWrapper(getTargetContext()){@Override public android.content.SharedPreferences getSharedPreferences(String ignored,int mode){return getBaseContext().getSharedPreferences(name,mode);}};android.content.SharedPreferences prefs=sandbox.getSharedPreferences(name,0);prefs.edit().putString("current",old.getString("current")).putString("records",old.getString("records")).putString("days",old.getString("days")).putBoolean("motion",old.optBoolean("motion",true)).putBoolean("haptic",old.optBoolean("haptic",true)).putBoolean("quickMode",old.optBoolean("quickMode")).putInt("themeId",old.optInt("themeId")).putInt("appearanceDefaults",old.optInt("appearanceDefaults",1)).commit();Class<?> type=Class.forName("com.tankecho.zensudoku.Store");Object store=type.getConstructor(Context.class).newInstance(sandbox),game=call(store,"load",new Class[]{});JSONObject previous=new JSONObject(old.getString("current"));ok(game!=null,"legacy game loads");String encoded=(String)game.getClass().getMethod("encode",int[].class).invoke(null,field(game,"board"));ok(encoded.equals(previous.getString("board")),"legacy board preserved");ok((Integer)field(game,"hints")==previous.getInt("hints")&&(Integer)field(game,"mistakes")==previous.getInt("mistakes"),"legacy budgets preserved");ok((Long)field(game,"elapsedMs")==previous.getLong("ms"),"legacy elapsed time preserved");ok(!(Boolean)field(game,"practice")&&!(Boolean)call(game,"canUndo",new Class[]{}),"legacy game defaults to challenge with no invented undo");ok(((JSONObject)field(store,"records")).length()==new JSONObject(old.getString("records")).length(),"legacy history count preserved");call(store,"save",new Class[]{game.getClass()},game);type.getMethod("awaitWrites").invoke(null);JSONObject saved=new JSONObject(prefs.getString("current",""));ok(saved.has("undo")&&saved.has("practice")&&saved.has("pendingHintCell"),"legacy game upgraded to complete v17 format");String backup=(String)call(store,"exportBackup",new Class[]{});type.getMethod("validateBackup",String.class).invoke(null,backup);ok(true,"migrated legacy state exports a valid backup");out.putString("stream",log+"LEGACY_V17_SUCCESS "+checks);finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream",log+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
